<script>
document.addEventListener('DOMContentLoaded', () => {
 const form=document.querySelector('[data-stock-import-form]'); if(!form)return;
 const preview=form.querySelector('[data-stock-import-preview]'), body=preview.querySelector('tbody'), errors=form.querySelector('[data-stock-import-errors]'), submit=form.querySelector('[data-stock-import-submit]');
 form.querySelector('[data-stock-import-file]').addEventListener('change', () => { submit.disabled=true; preview.classList.add('hidden'); errors.classList.add('hidden'); });
 form.querySelector('[data-stock-import-preview-button]').addEventListener('click', async () => { const file=form.querySelector('[data-stock-import-file]').files[0]; if(!file){errors.textContent='Pilih file Excel terlebih dahulu.';errors.classList.remove('hidden');return;} const data=new FormData();data.append('file',file); try{const response=await fetch('{{ route('stock-opname.import-preview') }}',{method:'POST',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:data});const result=await response.json();if(!response.ok){throw new Error(Object.values(result.errors||{}).flat().join(' ')||result.message||'File tidak valid.');}body.innerHTML=(result.rows||[]).map(row=>`<tr class="border-t border-[#edf1f5]"><td class="p-2">${row.row}</td><td class="p-2">${row.kode_internal}</td><td class="p-2">${row.nama_barang}</td><td class="p-2">${row.kategori}</td><td class="p-2">${row.satuan}</td><td class="p-2">${row.stok}</td><td class="p-2 ${row.errors.length?'text-[#b42318]':'text-[#08714e]'}">${row.errors.length?row.errors.join(' '):'Valid'}</td></tr>`).join('');preview.classList.remove('hidden');errors.innerHTML=(result.errors||[]).map(error=>`<div>${error}</div>`).join('');errors.classList.toggle('hidden',result.valid);submit.disabled=!result.valid;}catch(e){errors.textContent=e.message||'Preview tidak dapat dimuat. Periksa file Excel lalu coba kembali.';errors.classList.remove('hidden');submit.disabled=true;}});
});
</script>
@endonce
